/// Indonesian crisis-language detector for the AI companion.
///
/// Keyword-based first-pass detection. Designed to err on the side of caution
/// (false positives are acceptable — surfacing the crisis overlay when the user
/// is venting is much safer than missing a real suicidal ideation cue).
///
/// The actual empathetic response is generated by the LLM via the system
/// prompt's CRISIS PROTOCOL section; this detector only drives local UI
/// (the crisis overlay) and the `crisis_detected` flag stored on the
/// conversation row in Supabase.
abstract final class CrisisDetector {
  /// Indonesian + common Indonesian-English crisis phrases.
  /// Normalized to lowercase; partial substring matching is used.
  static const _keywords = <String>[
    // Explicit suicidal ideation
    'bunuh diri',
    'bundir',
    'mati saja',
    'pengen mati',
    'pengin mati',
    'ingin mati',
    'mau mati',
    'lebih baik mati',
    'lebih baik kalau aku mati',
    'mati aja',
    'mati aja deh',
    'akhiri hidup',
    'mengakhiri hidup',
    'menyudahi hidup',
    'akhiri saja semua',

    // Hopelessness / unwillingness to live
    'tidak mau hidup',
    'gak mau hidup',
    'ga mau hidup',
    'tak mau hidup',
    'tidak ada gunanya hidup',
    'tidak ada artinya hidup',
    'hidup tidak berarti',
    'hidup gak berarti',
    'percuma hidup',
    'kalau aku tidak ada',
    'kalau aku gak ada',
    'kalo aku ga ada',

    // Exhaustion / breaking point
    'sudah tidak kuat',
    'udah tidak kuat',
    'udah gak kuat',
    'gak kuat lagi',
    'ga kuat lagi',
    'tak kuat lagi',
    'tidak sanggup lagi',

    // Self-harm
    'menyakiti diri',
    'menyakiti diriku',
    'menyakiti diri sendiri',
    'melukai diri',
    'melukai diri sendiri',
    'menyayat',
    'self harm',
    'self-harm',
    'overdosis',
  ];

  /// Returns `true` when [text] contains any tracked crisis phrase.
  static bool detect(String text) {
    if (text.isEmpty) return false;
    final lower = text.toLowerCase();
    for (final kw in _keywords) {
      if (lower.contains(kw)) return true;
    }
    return false;
  }
}
